// Host tests for the Loomx node report (GET /loomx/node, schema loomx-node/1),
// the shared E1.31 pixel math (wled00/loomx_dmx_math.h) and the per-output limits.
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {execFileSync} = require('node:child_process');
const root = path.resolve(__dirname, '..');
const read = (file) => fs.readFileSync(path.join(root, file), 'utf8');

// Shape of loomx-node/1. Sense/Form parse exactly these fields.
const SCHEMA = {
  schema: 'string', id: 'string', mac: 'string', model: 'string', name: 'string',
  fw: {wled: 'string', loomx: 'string', commit: 'string'},
  net: {ip: 'string', mask: 'string', gw: 'string', dhcp: 'boolean', link: 'string',
        rssi: 'number', channel: 'number', hostname: 'string'},
  e131: {enabled: 'boolean', multicast: 'boolean', port: 'number', startUniverse: 'number',
         startAddress: 'number', mode: 'string', maxUniverses: 'number'},
  outputs: [{index: 'number', pin: 'number', len: 'number', maxLen: 'number', type: 'string',
             order: 'string', startPixel: 'number', universe: 'number', dmxChannel: 'number',
             endUniverse: 'number', endDmxChannel: 'number'}],
  totalPixels: 'number', universeCount: 'number', configRev: 'number', uptime: 'number',
  freeHeap: 'number',
};

function validate(value, schema, where = '$') {
  if (Array.isArray(schema)) {
    assert.ok(Array.isArray(value), `${where} must be an array`);
    value.forEach((item, i) => validate(item, schema[0], `${where}[${i}]`));
    return;
  }
  if (typeof schema === 'object') {
    assert.equal(typeof value, 'object', `${where} must be an object`);
    for (const [key, type] of Object.entries(schema)) {
      assert.ok(key in value, `${where}.${key} is missing`);
      validate(value[key], type, `${where}.${key}`);
    }
    return;
  }
  assert.equal(typeof value, schema, `${where} must be a ${schema}`);
}

function keysOf(schema, out = new Set()) {
  if (Array.isArray(schema)) return keysOf(schema[0], out);
  if (typeof schema === 'object') {
    for (const [key, type] of Object.entries(schema)) { out.add(key); keysOf(type, out); }
  }
  return out;
}

test('fixture matches the loomx-node/1 schema', () => {
  const node = JSON.parse(read('tools/fixtures/loomx-node-1.json'));
  validate(node, SCHEMA);
  assert.equal(node.schema, 'loomx-node/1');
  assert.match(node.id, /^[0-9a-f]{12}$/);
  assert.equal(node.mac.replace(/:/g, ''), node.id);
  assert.match(node.model, /^VX[48]$/);
  assert.ok(['eth', 'wifi', 'none'].includes(node.net.link));
});

test('firmware serializer emits every schema key and serves the route without a PIN', () => {
  const source = read('wled00/loomx_node.cpp');
  for (const key of keysOf(SCHEMA)) {
    const emitted = source.includes(`F("${key}")`) || source.includes(`["${key}"]`);
    assert.ok(emitted, `loomx_node.cpp does not emit "${key}"`);
  }
  assert.ok(source.includes('F("loomx-node/1")'));
  const server = read('wled00/wled_server.cpp');
  const route = server.slice(server.indexOf('F("/loomx/node")'));
  assert.ok(route.startsWith('F("/loomx/node"), HTTP_GET'));
  const handler = route.slice(0, route.indexOf('});'));
  assert.ok(!/settingsPIN|correctPIN|checkSettingsPIN/.test(handler), '/loomx/node must not require a PIN');
});

test('mDNS _loomx._tcp is advertised next to _wled._tcp with id/model/ver/uni/rev', () => {
  const wled = read('wled00/wled.cpp');
  const wledService = wled.indexOf('MDNS.addService("wled", "tcp", 80)');
  assert.ok(wledService > 0 && wled.indexOf('loomxBeginMdns()', wledService) > 0);
  const source = read('wled00/loomx_node.cpp');
  assert.ok(source.includes('MDNS.addService("loomx", "tcp", 80)'));
  for (const key of ['id', 'model', 'ver', 'uni', 'rev'])
    assert.ok(source.includes(`MDNS.addServiceTxt("loomx", "tcp", "${key}"`), `TXT ${key}`);
});

test('configRev is persisted, bumped on every cfg.json write and never set remotely', () => {
  const cfg = read('wled00/cfg.cpp');
  const writer = cfg.slice(cfg.indexOf('void serializeConfigToFS()'), cfg.indexOf('void serializeConfig(JsonObject root)'));
  assert.ok(writer.indexOf('loomxConfigRev++') < writer.indexOf('serializeConfig(root)'));
  assert.ok(writer.includes('loomxAnnouncePending = true'));
  assert.ok(cfg.includes('if (fromFS) loomxConfigRev = doc[F("loomx")][F("rev")]'));
  assert.ok(cfg.includes('loomxCfg[F("rev")] = loomxConfigRev'));
  // The announce is a one-shot sys-info packet independent of nodeBroadcastEnabled.
  const announce = read('wled00/loomx_node.cpp');
  const body = announce.slice(announce.indexOf('void loomxHandleAnnounce()'));
  assert.ok(body.includes('sendSysInfoUDP()') && !body.includes('nodeBroadcastEnabled'));
  assert.ok(read('wled00/wled.cpp').includes('loomxHandleAnnounce();'));
});

test('ESP32 builds accept 48 universes; ESP8266 stays at 9', () => {
  const constH = read('wled00/const.h');
  const block = constH.slice(constH.indexOf('#ifndef E131_MAX_UNIVERSE_COUNT'));
  assert.match(block, /#ifdef ESP8266\s+#define E131_MAX_UNIVERSE_COUNT 9\s+#else\s+#define E131_MAX_UNIVERSE_COUNT 48/);
  assert.ok(!/WLED_USE_ETHERNET\s+#define E131_MAX_UNIVERSE_COUNT 20/.test(constH));
});

test('900 pixels per output are enforced in firmware and the node UI', () => {
  assert.match(read('wled00/const.h'), /#define LOOMX_MAX_LEDS_PER_OUTPUT 900/);
  assert.ok(read('wled00/bus_manager.h').includes('count > LOOMX_MAX_LEDS_PER_OUTPUT) count = LOOMX_MAX_LEDS_PER_OUTPUT'));
  assert.ok(read('wled00/cfg.cpp').includes('length > LOOMX_MAX_LEDS_PER_OUTPUT'));
  const ui = read('loomx/ui/index.htm');
  assert.ok(ui.includes('var MAX_OUTPUT_PX=900;'));
  assert.ok(!ui.includes('clamp(o.len+d,0,2000)'));
  assert.ok(ui.includes('clamp(parseInt(digits,10),0,MAX_OUTPUT_PX)'));
});

// The extracted math is compiled on the host and checked against the original
// receiver formula (pre-extraction e131.cpp) and the expected universe counts.
const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'loomx-dmx-'));
fs.writeFileSync(path.join(directory, 'test.cpp'), String.raw`
#include "loomx_dmx_math.h"
#include <cassert>
#include <cstdio>
#include <cstring>
using namespace loomx;

// Original e131.cpp receiver formula, kept here as the reference.
static unsigned refPrevious(bool rgbw, bool dimmer, unsigned addr, unsigned prevUni) {
  const unsigned cpl = rgbw ? 4 : 3, per = rgbw ? 128 : 170, dim = dimmer ? 1 : 0;
  const unsigned lenOff = addr == 0 ? 0 : 1;
  unsigned first = (((512 - addr) + lenOff) - dim) / cpl;
  return prevUni == 0 ? 0 : first + (prevUni - 1) * per;
}

int main(int argc, char** argv) {
  const char* s = argc > 1 ? argv[1] : "";
  if (!strcmp(s, "reference")) {
    for (int rgbw = 0; rgbw < 2; rgbw++) for (int dim = 0; dim < 2; dim++)
      for (unsigned addr = 0; addr <= 510; addr++) for (unsigned u = 0; u < 48; u++) {
        DmxLayout l = dmxLayout(rgbw, dim, addr);
        assert(previousLeds(l, u) == refPrevious(rgbw, dim, addr, u));
      }
  }
  if (!strcmp(s, "rgb")) {
    DmxLayout l = dmxLayout(false, false, 1);
    assert(l.ledsInFirstUniverse == 170 && l.ledsPerUniverse == 170 && l.channelsPerLed == 3);
    DmxAddress a = pixelAddress(l, 1, 1, 0);   assert(a.universe == 1 && a.channel == 1);
    a = pixelAddress(l, 1, 1, 169);            assert(a.universe == 1 && a.channel == 508);
    a = pixelAddress(l, 1, 1, 170);            assert(a.universe == 2 && a.channel == 1);
    a = pixelAddress(l, 5, 1, 340);            assert(a.universe == 7 && a.channel == 1);
    assert(universeCount(l, 170) == 1 && universeCount(l, 171) == 2 && universeCount(l, 0) == 1);
  }
  if (!strcmp(s, "rgbw")) {
    DmxLayout l = dmxLayout(true, false, 1);
    assert(l.ledsInFirstUniverse == 128 && l.ledsPerUniverse == 128 && l.channelsPerLed == 4);
    DmxAddress a = pixelAddress(l, 1, 1, 127); assert(a.universe == 1 && a.channel == 509);
    a = pixelAddress(l, 1, 1, 128);            assert(a.universe == 2 && a.channel == 1);
    assert(universeCount(l, 900) == 8);
  }
  if (!strcmp(s, "mid")) {
    // Start address 101: the first universe holds (513 - 101) / 3 = 137 pixels.
    DmxLayout l = dmxLayout(false, false, 101);
    assert(l.ledsInFirstUniverse == 137);
    DmxAddress a = pixelAddress(l, 3, 101, 0);  assert(a.universe == 3 && a.channel == 101);
    a = pixelAddress(l, 3, 101, 136);           assert(a.universe == 3 && a.channel == 509);
    a = pixelAddress(l, 3, 101, 137);           assert(a.universe == 4 && a.channel == 1);
    // DRGB keeps slot 1 for the dimmer.
    DmxLayout d = dmxLayout(false, true, 1);
    assert(d.ledsInFirstUniverse == 170);
    a = pixelAddress(d, 1, 1, 0);               assert(a.universe == 1 && a.channel == 2);
  }
  if (!strcmp(s, "limits")) {
    DmxLayout l = dmxLayout(false, false, 1);
    // One 900 px output: 6 universes.
    assert(universeCount(l, 900) == 6);
    // 8 outputs x 900 px RGB, contiguous as the node receives them: 43 universes.
    assert(universeCount(l, 8 * 900) == 43 && universeCount(l, 8 * 900) <= 48);
    // With per-output universe alignment (each output starts a fresh universe): 48.
    assert(8 * universeCount(l, 900) == 48);
    // Output starts across 8 x 900 px land inside the 48-universe window.
    for (unsigned o = 0; o < 8; o++) {
      DmxAddress last = pixelAddress(l, 1, 1, o * 900 + 899);
      assert(last.universe - 1 < 48);
    }
    // RGBW 8 x 900 needs 57 universes: more than one node window, reported.
    DmxLayout w = dmxLayout(true, false, 1);
    assert(universeCount(w, 8 * 900) == 57);
  }
  std::puts("ok");
  return 0;
}
`);
execFileSync('c++', ['-std=c++17', '-Wall', '-Wextra', '-Werror', '-I', path.join(root, 'wled00'),
  path.join(directory, 'test.cpp'), '-o', path.join(directory, 'test')]);
for (const [scenario, description] of Object.entries({
  reference: 'extracted math equals the original e131.cpp formula for every start address',
  rgb: 'RGB: 170 pixels per universe, pixel 170 starts the next universe at slot 1',
  rgbw: 'RGBW: 128 pixels per universe',
  mid: 'mid-universe start address and DRGB dimmer slot',
  limits: '900 px outputs and 8 outputs fit in 48 universes',
})) test(description, () => execFileSync(path.join(directory, 'test'), [scenario]));
